/**
 * Tera's accessories as painted image layers, aligned to his face art (240 x 368, the same box as
 * `guideFaces`). Each outfit is a `back` layer (under the face image) and a `front` layer (over it);
 * the front exists per face tile where the accessory passes behind his crest or beak, because the
 * crest is painted a little differently on each tile. Nothing here redraws Tera.
 *
 * The layers are generated by `design-playground/tera-outfits/build.py` into `public/mascot/outfits/`
 * on a canvas with a 24 unit bleed around the face box (288 x 416), so an accessory can pop out of
 * the ring the way his crest does. The on-chain art inlines the same files
 * (`supabase/functions/_shared/outfit-art.ts`).
 */
export const OUTFIT_BOX = { width: 240, height: 368 } as const;
/** Transparent margin around the face box, in box units, on every side of a layer image. */
export const OUTFIT_BLEED = 24;
export const OUTFIT_LAYER = { width: OUTFIT_BOX.width + 2 * OUTFIT_BLEED, height: OUTFIT_BOX.height + 2 * OUTFIT_BLEED } as const;

export type OutfitKey = 'outfit_glasses' | 'outfit_crown' | 'outfit_headphones' | 'outfit_laurel';
/** The face tiles a front layer can be cut for; blink shares neutral. */
export type OutfitFace = 'neutral' | 'happy' | 'oops';

export interface OutfitArt {
  back: string | null;
  front: Record<OutfitFace, string>;
}

export const OUTFIT_KEYS: readonly OutfitKey[] = ['outfit_glasses', 'outfit_headphones', 'outfit_crown', 'outfit_laurel'];
export const OUTFIT_FACES: readonly OutfitFace[] = ['neutral', 'happy', 'oops'];

const BASE = '/mascot/outfits';
const perFace = (key: OutfitKey): Record<OutfitFace, string> => ({
  neutral: `${BASE}/${key}-front.webp`,
  happy: `${BASE}/${key}-front-happy.webp`,
  oops: `${BASE}/${key}-front-oops.webp`,
});
const oneFront = (key: OutfitKey): Record<OutfitFace, string> => {
  const src = `${BASE}/${key}-front.webp`;
  return { neutral: src, happy: src, oops: src };
};

export const OUTFITS: Record<OutfitKey, OutfitArt> = {
  outfit_glasses: { back: null, front: perFace('outfit_glasses') },
  outfit_headphones: { back: null, front: perFace('outfit_headphones') },
  outfit_crown: { back: null, front: perFace('outfit_crown') },
  // frames the ring and never touches the crest, so one front fits every face
  outfit_laurel: { back: `${BASE}/outfit_laurel-back.webp`, front: oneFront('outfit_laurel') },
};

const ALIASES: Record<string, OutfitKey> = { glasses: 'outfit_glasses', crown: 'outfit_crown', headphones: 'outfit_headphones', laurel: 'outfit_laurel' };

const has = (map: object, key: string) => Object.prototype.hasOwnProperty.call(map, key);

/** The drawable outfit behind an item key or a bare name; null for none, unknown or non-outfit keys. */
export function outfitOf(key: string | null | undefined): OutfitKey | null {
  if (!key) return null;
  const k = key.trim().toLowerCase();
  if (has(OUTFITS, k)) return k as OutfitKey;
  return has(ALIASES, k) ? ALIASES[k] : null;
}

/** What Tera wears on a surface: a previewed outfit wins over the equipped one; `null` preview means "take it off". */
export function selectOutfit(equipped: string | null | undefined, preview?: string | null): OutfitKey | null {
  return preview === undefined ? outfitOf(equipped) : outfitOf(preview);
}

/** The distinct front images of an outfit, so every face's cut can sit in the DOM and swap without a flash. */
export function frontSources(key: OutfitKey): string[] {
  return [...new Set(OUTFIT_FACES.map((face) => OUTFITS[key].front[face]))];
}
